def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != background]
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if grid[r1][c] == background:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if grid[r][c1] == background:
                        out[r][c1] = 3
    return out
